import json, os, glob
d='/home/rudra/Projects/OpenCode-Vault/control-plane/decision-queue/cards'
fixed=0; ok=0; failed=[]
for p in sorted(glob.glob(d+'/*.json')):
    raw=open(p,encoding='utf-8').read()
    try:
        json.loads(raw); ok+=1; continue
    except json.JSONDecodeError:
        pass
    dec=json.JSONDecoder()
    objs=[]; i=0; n=len(raw)
    while i<n:
        while i<n and raw[i].isspace(): i+=1
        if i>=n: break
        try:
            o,j=dec.raw_decode(raw,i); objs.append(o); i=j
        except json.JSONDecodeError as e:
            failed.append((p,str(e))); objs=None; break
    if objs:
        tmp=p+'.tmp'
        with open(tmp,'w',encoding='utf-8') as f: json.dump(objs[0],f,ensure_ascii=False,indent=2); f.write('\n')
        os.rename(tmp,p); fixed+=1
print(f"ok={ok} fixed={fixed} failed={len(failed)}")
for f in failed: print(f)
EOF
